/**
 * Insert and approve follow-up emails generated by Claude agents.
 * Usage: node scripts/insert-followups.js <followups-json-file>
 *
 * Input JSON format: [{prospect_id, campaign_id, step2_subject, step2_body, step3_subject, step3_body}]
 */
const https = require('https');
const fs = require('fs');

const file = process.argv[2];
if (!file) { console.error('Usage: node insert-followups.js <file.json>'); process.exit(1); }

let TOKEN = '';
const post = (p, b) => new Promise((r, j) => {
  const d = JSON.stringify(b);
  const o = { hostname: 'abm.tecnociminnova.com', path: p, method: 'POST',
    headers: { 'Authorization': 'Bearer ' + TOKEN, 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(d) },
    rejectUnauthorized: false };
  const q = https.request(o, s => { let dd = ''; s.on('data', c => dd += c); s.on('end', () => { try { r(JSON.parse(dd)); } catch (e) { j(new Error(dd.substring(0, 200))); } }); });
  q.on('error', j); q.write(d); q.end();
});
const get = (p) => new Promise((r, j) => {
  const o = { hostname: 'abm.tecnociminnova.com', path: p, method: 'GET',
    headers: { 'Authorization': 'Bearer ' + TOKEN }, rejectUnauthorized: false };
  const q = https.request(o, s => { let d = ''; s.on('data', c => d += c); s.on('end', () => { try { r(JSON.parse(d)); } catch (e) { j(new Error(d.substring(0, 200))); } }); });
  q.on('error', j); q.end();
});

(async () => {
  // Login
  const login = await post('/api/auth/login', { email: 'alfons.marques@tecnocim.com', password: process.env.ABM_PASSWORD, tenant_slug: 'tecnocim' });
  if (!login.success) { console.log('Login failed:', login.error); return; }
  TOKEN = login.data.token;

  const followups = JSON.parse(fs.readFileSync(file, 'utf8'));
  console.log('Loaded:', followups.length, 'prospects from', file);

  // QA + build payload
  const byCampaign = {};
  let qaFails = 0;

  for (const f of followups) {
    for (const [stepKey, stepNum, delayDays] of [['step2', 2, 3], ['step3', 3, 7]]) {
      const subj = f[stepKey + '_subject'];
      const body = f[stepKey + '_body'];
      if (!subj || !body) { console.error('MISSING:', f.email || f.prospect_id, stepKey); qaFails++; continue; }

      const all = (subj + ' ' + body).toLowerCase();
      if (/unknown/i.test(all)) { console.error('QA FAIL Unknown:', f.prospect_id, stepKey); qaFails++; }
      if (/batch\s*\d/i.test(all)) { console.error('QA FAIL Batch:', f.prospect_id, stepKey); qaFails++; }
      if (/deducciones i\+d\+i 2026/i.test(all)) { console.error('QA FAIL CampName:', f.prospect_id, stepKey); qaFails++; }

      const campId = f.campaign_id;
      if (!byCampaign[campId]) byCampaign[campId] = [];
      byCampaign[campId].push({ prospect_id: f.prospect_id, step_number: stepNum, delay_days: delayDays, subject: subj, body_html: body });
    }
  }

  console.log('QA fails:', qaFails);
  if (qaFails > 0) { console.log('ABORTING — fix QA issues first'); return; }

  // Bulk insert
  let totalInserted = 0;
  for (const [campId, emails] of Object.entries(byCampaign)) {
    for (let i = 0; i < emails.length; i += 100) {
      const batch = emails.slice(i, i + 100);
      const r = await post('/api/campaigns/' + campId + '/bulk-insert-emails', { emails: batch });
      totalInserted += r.data?.inserted || 0;
    }
    console.log(campId.substring(0, 8) + ': ' + emails.length + ' inserted');
  }
  console.log('Total inserted:', totalInserted);

  // Approve
  for (const [campId] of Object.entries(byCampaign)) {
    let page = 1, draftIds = [];
    while (true) {
      const r = await get('/api/campaigns/' + campId + '/generated-emails?status=draft&limit=200&page=' + page);
      (r.data?.emails || []).forEach(e => draftIds.push(e.id));
      if (!r.pagination || page >= r.pagination.totalPages) break;
      page++;
    }
    if (draftIds.length === 0) continue;
    for (let i = 0; i < draftIds.length; i += 200) {
      const batch = draftIds.slice(i, i + 200);
      const r = await post('/api/campaigns/' + campId + '/approve-emails', { email_ids: batch });
      console.log(campId.substring(0, 8) + ' approved:', r.data?.count || 0);
    }
  }

  console.log('\nDone!');
})().catch(e => console.error('Fatal:', e.message));
